def normalize_tags(tags):
    if not tags:
        return None

    seen = set()
    result = []
    for tag in tags:
        key = tag.casefold() if isinstance(tag, str) else tag
        if key not in seen:
            seen.add(key)
            result.append(tag)
    return tuple(result)

def most_common_word(words):
    counts = {}
    originals = {}

    for word in words:
        key = word.casefold() if isinstance(word, str) else word
        if key not in counts:
            counts[key] = 0
            originals[key] = word
        counts[key] += 1

    if not counts:
        return None

    best_key = max(counts, key=counts.get)
    return originals[best_key]

def intersection_labels(first, second):
    if len(first) == 0 or len(second) == 0:
        return None

    def key(label):
        if isinstance(label, str):
            return ("string", label.casefold())
        return ("other", label)

    second_keys = {key(label) for label in second}
    seen = set()
    result = []

    for label in first:
        normalized = key(label)
        if normalized in second_keys and normalized not in seen:
            seen.add(normalized)
            result.append(label)

    return tuple(result)

def common_suffix(words):
    if not words:
        return None

    shortest = min(words, key=len)
    for length in range(len(shortest), 0, -1):
        suffix = shortest[-length:]
        if all(word.endswith(suffix) for word in words):
            return suffix
    return ""

def parse_clock(text):
    import re

    match = re.fullmatch(r"\s*(\d{1,2}):(\d{2})\s+(AM|PM)\s*", text, re.IGNORECASE)
    if not match:
        raise ValueError("Invalid clock time")

    hour, minute = int(match.group(1)), int(match.group(2))
    if not 1 <= hour <= 12 or minute > 59:
        raise ValueError("Invalid clock time")

    period = match.group(3).upper()
    hour %= 12
    if period == "PM":
        hour += 12
    return hour * 60 + minute

from datetime import datetime

def sort_events(events):
    if not events:
        return None
    return tuple(sorted(events, key=lambda event: datetime.fromisoformat(event["time"])))

def matrix_multiply(left, right):
    if not left or not right:
        return None

    columns = len(right[0])
    return tuple(
        tuple(
            sum(row[k] * right[k][j] for k in range(len(row)))
            for j in range(columns)
        )
        for row in left
    )

def count_islands(grid):
    if not grid:
        return None

    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    islands = 0

    for row in range(rows):
        for col in range(cols):
            if grid[row][col] != 1 or (row, col) in visited:
                continue

            islands += 1
            stack = [(row, col)]
            visited.add((row, col))

            while stack:
                current_row, current_col = stack.pop()
                for next_row, next_col in (
                    (current_row - 1, current_col),
                    (current_row + 1, current_col),
                    (current_row, current_col - 1),
                    (current_row, current_col + 1),
                ):
                    if (
                        0 <= next_row < rows
                        and 0 <= next_col < cols
                        and grid[next_row][next_col] == 1
                        and (next_row, next_col) not in visited
                    ):
                        visited.add((next_row, next_col))
                        stack.append((next_row, next_col))

    return islands
